import { MeshBasicNodeMaterial, PlaneGeometry, Group, Mesh } from 'three/webgpu';
import { uv, vec3, mix, uniform, texture, fract, sin, dot } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new Group();

  const position = config.scenePlacement?.position || [0, -0.3, 0];
  const rotation = config.scenePlacement?.rotation || [0, 0, 0];
  const scale = config.scenePlacement?.scale || [1, 1, 1];

  group.position.set(position[0], position[1], position[2]);
  group.rotation.set(rotation[0], rotation[1], rotation[2]);
  group.scale.set(scale[0], scale[1], scale[2]);

  // Card geometry (aspect ratio from atlas source 512×320 → 1.6:1)
  const geometry = new PlaneGeometry(2.0, 1.25);
  const material = new MeshBasicNodeMaterial();

  // Colors from spec
  const surfaceColor = vec3(0.043, 0.043, 0.063);      // #0b0b10
  const paperColor   = vec3(0.910, 0.925, 0.949);      // #e8ecf2
  const accentColor  = vec3(1.0, 0.165, 0.22);         // #ff2a38 (unused, but available)

  // Texture uniform for the orb-decor image
  const texUniform = uniform();

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texUniform.value = tex;
    });
  }

  // UV coordinates
  const u = uv();

  // Vertical gradient from surface (bottom) to paper (top)
  const gradient = mix(surfaceColor, paperColor, u.y);

  // Texture sample (when loaded)
  const texColor = texture(texUniform, u);

  // Subtle grain noise (procedural)
  const noiseValue = fract(sin(dot(u * 40.0, vec3(12.9898, 78.233, 45.164))) * 43758.5453);
  const grain = (noiseValue - 0.5) * 0.08; // 8% intensity

  // Combine: texture + gradient overlay + grain
  const finalColor = mix(gradient, texColor, 0.85) + grain;

  material.outputNode = vec4(finalColor, 1.0);

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texUniform.value) texUniform.value.dispose();
    // No GSAP timelines to kill
  };

  // No handlers (static)
  group.userData.handlers = {};

  return group;
}
